  "team.bio.hamed": "Teacher and guide of the team for these competitions. A specialist engineer and AI programmer, guiding the team's work on Challenge 4.",
  "team.bio.models": "Worked on the design and training of this project's trained models: how the check's signals are combined into one risk, how that model is trained, and how it is measured on answers it has never seen.",
  "team.bio.sepehr": "Consulting and coordination for the team, and UI/UX design: how the pages present a check so it can be read at a glance.",
  "team.bio.majid": "Synchronising the project's models, and UI/UX design: how the models for text, sound and images work together in one engine, and how the pages show them clearly.",
  "about.title": "About Truth Guardian",
  "about.lead": "Truth Guardian is our entry to the iWISE 2026 AI Challenge 4 on hallucination detection: a guardian that reads an AI's answer beside its evidence, finds the words the evidence does not support, explains why, and fixes what it can.",
  "about.challengeTitle": "The challenge",
  "about.challengeBody": "AI systems answer fluently even when they are wrong. The challenge is to tell whether an answer is grounded in its retrieved documents or hallucinated, how great the risk is, which parts are suspect and on what evidence, for a single answer and for a multi-step agent alike. Truth Guardian does that for text first and, as the project's own additions, can set a flagged answer right from its sources and also checks answers about a recording or a picture against what was said or what is written in it.",
  "about.engineTitle": "How the engine works",
  "about.engineBody": "For an answer written from text sources, five stages run one after another on this computer. Each stage adds evidence the next one uses, and every verdict can be traced back to the words that caused it.",
  "about.s1.label": "Evidence",
  "about.s1.title": "Find the evidence for every sentence",
  "about.s1.sub": "Each sentence of the answer is matched to the source passages that could support it, by keywords (BM25) and by meaning, fused by rank.",
  "about.s2.label": "Signals",
  "about.s2.title": "Read it four different ways",
  "about.s2.sub": "Word overlap, numbers, names and dates checked one by one, meaning similarity, and HHEM, a model trained to judge factual consistency.",
  "about.s3.label": "Fusion",
  "about.s3.title": "Turn them into one calibrated risk",
  "about.s3.sub": "A learned ensemble weighs the signals for every sentence and for the whole answer; its risk reads as a probability.",
  "about.s4.label": "Rules",
  "about.s4.title": "Catch what models miss",
  "about.s4.sub": "Flipped negations and opposites confirmed by NLI, swapped roles, overclaims, sources that disagree, citations that point elsewhere.",
  "about.s5.label": "Report",
  "about.s5.title": "Explain, fix, guarantee",
  "about.s5.sub": "Exact words, evidence, a fix from the sources, who is to blame, what was left out, a statistical guarantee, a triage lane and a grade.",
  "about.runsTitle": "Where the processing happens",
  "about.runsBody": "Everything runs on an ordinary laptop processor, with no graphics card and no internet connection. The language models are kept inside the project folder, the heaviest one runs through ONNX Runtime, and repeated sentences are answered from a cache, so a check takes a few seconds. No answer or source leaves the computer.",
  "contact.title": "Contact us",
  "contact.lead": "A question, a suggestion or a problem to report? Write to the Truth Guardian team; your message goes straight to our mailbox and we answer by email.",
