  "card.short.dialogue": "Dialogue",
  "card.short.summary": "Summary",
  "card.limit1": "Trained and calibrated on RAGTruth (English news, QA and business data). On another domain the ranking holds less well (locked HaluEval dialogue 0.67 and summary 0.69 AUROC, calibration error about 0.23) until a domain profile is fitted on a few dozen labelled answers; with 50, dialogue rises to about 0.72 and summary to 0.79 on answers the profile did not see, and the calibration error falls to about 0.07.",
  "card.limit2": "Some edits still slip through: an opposite word is caught 45% of the time, a stronger quantifier 57% and a dropped hedge 37% (up from 37% and 20% after D-114).",
  "card.limit3": "On natural agent runs (AgentHallu) no setting of the live guardian separates faithful from hallucinating agents well (detection AUROC about 0.53 on the locked test); three fixes tried out of fold made no difference (D-116). Finding the faulty step works better than chance, not reliably.",
  "card.limit4": "Span F1 on the locked RAGTruth test (0.30) is lower than on dev (0.38): the verdict for the whole answer holds up better than the exact place of the error. Exact words from the trained detector lift dev span F1 to 0.41; the locked test has not been opened again to measure it.",
  "card.limit5": "Healing edits are often right but not always: read the changes before using a healed answer.",
  "card.limit6": "It checks answers against the given sources only. A claim that is true in the world but absent from the sources counts as unsupported.",
  "card.title": "Reliability",
  "card.lead": "Every number on this page is read from the project's committed evaluation files. Thresholds were chosen on training or development data; the locked test set is opened once, at the end.",
