  "card.sameAnswers": "Same answers, thresholds from dev. On dev: Truth Guardian {a}, best baseline {b}.",
  "card.lettuceNote": " LettuceDetect is a published detector fine-tuned on RAGTruth train itself, so this test is its home ground; it finds the wrong words better (span F1 {s}) but ranks answers less well{halu}.",
  "card.lettuceHalu": "; on HaluEval QA / dialogue / summary it scores {v}",
