  "card.unseen": "On data it never saw (HaluEval, AUROC)",
  "card.unseenNote": "{n} answers per task, no tuning on HaluEval. Training: {t} RAGTruth answers, out-of-fold AUROC {a}.",
  "card.calibTitle": "Does a risk of 0.8 mean 80%? Predicted risk against how often the answers were really hallucinated",
  "card.calib1": "A point on the dashed line means the risk can be read as a probability: of the answers given a risk near 0.8, about 80% were hallucinated. Points below the line mean the risk runs high (cautious); above it, low.",
  "card.calib2": "On RAGTruth, where the model was calibrated, the points stay close to the line, on dev and on the locked test. On the test the middle of the scale runs a little high, so the guardian errs on the side of caution there.",
  "card.calib3": "On HaluEval, a domain it never saw, low risks are too low and high risks too high. This is why a domain profile, fitted on a few dozen labelled answers of the new domain, recalibrates the risk before the guarantees are used there.",
  "card.calibNote": "Ten equal-width risk bins, the same as the reported calibration error (ECE). Hover a point for its numbers.",
  "card.profilesTitle": "A new domain from {n} labelled answers: the shipped domain profiles, checked on answers they did not see",
  "card.colProfile": "Profile",
  "card.colChecked": "Answers checked",
  "card.colAurocArrow": "AUROC, model → profile",
  "card.colCalib": "Calibration error",
  "card.colVerdictAcc": "Verdict accuracy",
  "card.profilesNote": "Each profile re-weights the model's risk and three evidence signals averaged over the answer's sentences, recalibrates the risk and sets the domain's own guarantee lines and verdict. It never uses the answer's length: on HaluEval, length alone separates the labels{alone}, a shortcut no real domain offers. HaluEval external dev; the locked HaluEval sets were not used.",
