  "card.short.dialogue": "حوار",
  "card.short.summary": "تلخيص",
  "card.limit1": "دُرِّب وعويِر على RAGTruth (أخبار وأسئلة وأجوبة وبيانات أعمال بالإنجليزية). في مجال آخر يضعف الترتيب (AUROC على HaluEval المقفلة: الحوار 0.67 والتلخيص 0.69، وخطأ المعايرة نحو 0.23) حتى يُبنى ملف مجال على بضع عشرات من الإجابات الموسومة؛ مع 50 إجابة يرتفع الحوار إلى نحو 0.72 والتلخيص إلى 0.79 على إجابات لم يرها الملف، وينخفض خطأ المعايرة إلى نحو 0.07.",
  "card.limit2": "لا تزال بعض التعديلات تمر: تُكتشف الكلمة المضادة في 45% من الحالات، والمحدِّد الكمي الأقوى في 57%، والتحفّظ المحذوف في 37% (بعد أن كانت 37% و20% قبل D-114).",
  "card.limit3": "في تشغيلات الوكلاء الطبيعية (AgentHallu) لا يفصل أي إعداد للحارس المباشر الوكلاء السليمين عن الذين فيهم هلوسة فصلًا جيدًا (AUROC للكشف نحو 0.53 على الاختبار المقفل)؛ ولم تُحدث ثلاثة إصلاحات جُرّبت خارج الطيّة أي فرق (D-116). العثور على الخطوة المعيبة أفضل من الصدفة، لكنه غير موثوق.",
  "card.limit4": "Span F1 على اختبار RAGTruth المقفل (0.30) أقل منه على dev (0.38): الحكم على الإجابة كلها أمتن من تحديد موضع الخطأ بالضبط. ترفع الكلمات الدقيقة من الكاشف المدرَّب span F1 على dev إلى 0.41؛ ولم يُفتح الاختبار المقفل مجددًا لقياسها.",
  "card.limit5": "تعديلات الإصلاح صحيحة غالبًا لكن ليس دائمًا: اقرأ التغييرات قبل استخدام إجابة مصحَّحة.",
  "card.limit6": "يفحص الإجابات مقابل المصادر المعطاة فقط. الادعاء الصحيح في الواقع لكنه غائب عن المصادر يُعدّ غير مدعوم.",
  "card.title": "الموثوقية",
  "card.lead": "كل رقم في هذه الصفحة مقروء من ملفات التقييم المحفوظة في المشروع. اختيرت العتبات على بيانات التدريب أو التطوير؛ وتُفتح مجموعة الاختبار المقفلة مرة واحدة، في النهاية.",
