  "card.lettuce": "LettuceDetect (خارجي)",
  "card.sameAnswers": "الإجابات نفسها، والعتبات من dev. على dev: Truth Guardian {a}، وأفضل أسلوب مرجعي {b}.",
  "card.lettuceNote": " LettuceDetect كاشف منشور ضُبط على RAGTruth train نفسها، فهذا الاختبار ملعبه؛ يعثر على الكلمات الخاطئة أفضل (span F1 {s}) لكنه يرتّب الإجابات أسوأ{halu}.",
