  "card.unseenLockedNote": "{n} إجابة لكل مهمة، فُتحت مرة واحدة، دون أي ضبط على HaluEval؛ العتبات هي عتبات RAGTruth، لذا فالخطر هنا أقل معايرة. التدريب: {t} إجابة من RAGTruth.",
  "card.unseen": "على بيانات لم يرها قط (HaluEval، AUROC)",
  "card.unseenNote": "{n} إجابة لكل مهمة، دون أي ضبط على HaluEval. التدريب: {t} إجابة من RAGTruth، و AUROC خارج الطيّة {a}.",
  "card.calibTitle": "هل يعني خطر 0.8 نسبة 80%؟ الخطر المتوقَّع مقابل عدد المرات التي كانت فيها الإجابات فيها هلوسة فعلًا",
  "card.calib1": "تعني النقطة على الخط المتقطع أن الخطر يمكن قراءته كاحتمال: من الإجابات التي أُعطيت خطرًا قرب 0.8، نحو 80% كانت فيها هلوسة. النقاط تحت الخط تعني أن الخطر مرتفع (حذر)؛ وفوقه، منخفض.",
  "card.calib2": "على RAGTruth، حيث عويِر النموذج، تبقى النقاط قريبة من الخط، على dev وعلى الاختبار المقفل. على الاختبار يرتفع وسط المقياس قليلًا، فيميل الحارس إلى الحذر هناك.",
  "card.calib3": "على HaluEval، وهو مجال لم يره قط، تكون المخاطر المنخفضة منخفضة جدًا والمرتفعة مرتفعة جدًا. لهذا يعيد ملف المجال، المبني على بضع عشرات من الإجابات الموسومة من المجال الجديد، معايرة الخطر قبل استخدام الضمانات هناك.",
  "card.calibNote": "عشرة نطاقات خطر متساوية العرض، هي نفسها التي يُحسب عليها خطأ المعايرة (ECE) المذكور. مرّر المؤشر على نقطة لرؤية أرقامها.",
  "card.profilesTitle": "مجال جديد من {n} إجابة موسومة: ملفات المجال المرفقة، مفحوصة على إجابات لم ترها",
  "card.colProfile": "الملف",
  "card.colChecked": "الإجابات المفحوصة",
