  "card.colCalib": "خطأ المعايرة",
  "card.colVerdictAcc": "دقة الحكم",
  "card.profilesNote": "يعيد كل ملف وزن خطر النموذج وثلاث إشارات دليل متوسَّطة على جمل الإجابة، ويعيد معايرة الخطر ويحدد خطوط الضمان والحكم الخاصة بالمجال. لا يستخدم طول الإجابة أبدًا: على HaluEval يفصل الطول وحده بين الوسوم{alone}، وهو اختصار لا يوفره أي مجال حقيقي. HaluEval external dev؛ لم تُستخدم مجموعات HaluEval المقفلة.",
