  "html.free.by.both": "ذكرها النموذج ووجدها الحارس",
  "html.free.n.main": "أجاب نموذج مجاني على الإنترنت لأن المستندات لم تتضمن إجابة. فحصها الحارس هنا مقابل الصفحات التي ذكرها النموذج ومقالات ويكيبيديا التي وجدها بنفسه: الحكم «موثّقة» يعني أن الإجابة توافق ما وُجد، لا أن كل صفحة صحيحة.",
