  "html.seen.none": "لم يقرأ القارئ أي نص في هذه الصورة.",
  "html.free.n.opinion": "تستند هذه الإجابة إلى ما يقول نموذج الصور إنه يراه، وهو رأيه، فلا تُفحص مقابله؛ يُفحص فقط النص الذي تقول إنه في الصورة، مقابل ما قرأه قارئ مستقل.",
  "html.second.title.image": "رأي ثانٍ: نموذج آخر نظر إلى الصورة نفسها ({m})",
  "html.second.title.recording": "رأي ثانٍ: نموذج آخر استمع إلى التسجيل نفسه ({m})",
  "html.second.agreed": "النموذجان متفقان",
  "html.second.disputed": "النموذجان مختلفان: هلوسة محتملة",
  "html.second.unclear": "الرأي الثاني لا يؤكد الإجابة ولا ينقضها",
  "html.second.st.agreed": "متفق",
  "html.second.st.disputed": "مختلف",
  "html.second.st.unclear": "غير واضح",
  "html.second.said.image": "ما أجاب به النموذج الثاني:",
  "html.second.said.recording": "ما سمعه المستمع الثاني:",
  "html.second.read": "الكلمات التي قرأها النموذج الثاني في الصورة:",
  "html.second.caution": "اتفاق نموذجين ليس دليلًا؛ إنما يقلل احتمال الخطأ. وحيث يختلفان، فأحدهما على الأقل مخطئ.",
  "html.seen.disputed": "قرأ النموذجان نص الصورة بشكل مختلف: هلوسة محتملة",
  "html.seen.st.agreed": "قرأه النموذجان",
  "html.seen.st.disputed": "قُرئ بشكل مختلف",
  "html.seen.r.second_read": "لم يقرأ القارئ نصًا، لكن النموذج الثاني قرأ هذه الكلمات أيضًا",
  "html.seen.r.second_differs": "لم يقرأ القارئ نصًا، وقرأ النموذج الثاني شيئًا آخر",
  "html.lead": "يفحص حارس الحقيقة إجابة الذكاء الاصطناعي قبل أن تعتمد عليها. يُختبر النص جملةً جملة مقابل مستنداتك أو مصادر يجدها الحارس بنفسه (ويكيبيديا وويكي بيانات والبحث على الويب والأعمال العلمية)، ويُصنَّف كل مصدر بأنه مؤيد أو مناقض أو غير ذي صلة. تقرأ الصورَ والتسجيلات نموذجٌ محلي ثم نموذج مجاني عبر الإنترنت، وتُقارَن القراءتان. وينتهي كل فحص بحكم واضح، موثّقة أو مختلَقة، مع مستوى الخطر وأسبابه؛ تعمل النماذج المحلية دون اتصال ويُضاف الفحص عبر الإنترنت عند الاتصال.",
  "html.online.checking": "عبر الإنترنت · جارٍ الفحص…",
  "html.online.on": "عبر الإنترنت · النماذج متصلة",
  "html.online.partly": "عبر الإنترنت · متصل جزئيًا",
  "html.online.off": "عبر الإنترنت · غير متصل",
  "html.online.restart": "عبر الإنترنت · أعد تشغيل الخادم",
  "html.arch": "بنية النظام",
  "html.arch.lead": "كيف تعمل النماذج والحارس معًا، من قراءة الملف إلى الحكم: ست مراحل؛ المحلية منها على هذا الحاسوب ودون اتصال، والمتصلة مجانية ولا تُستخدم إلا عند الاتصال.",
  "html.arch.s1.t": "قراءة المدخلات",
  "html.arch.s1.d": "يُفرَّغ التسجيل نصًّا مع تحديد لغة كل مقطع، ويُقرأ النص الموجود في الصورة، ويُوصف ما تُظهره الصورة؛ وكل ذلك على هذا الحاسوب.",
  "html.arch.s2.t": "إيجاد الأدلة",
  "html.arch.s2.d": "تُستخرج أقرب المقاطع من مستنداتك بدمج مطابقة الكلمات مع التشابه في المعنى. وعبر الإنترنت، يبحث الحارس عن مصادره بنفسه بدل الاعتماد على مصادر النموذج.",
  "html.arch.s3.t": "كتابة الإجابة",
  "html.arch.s3.d": "يكتب النموذج المحلي الإجابة من تلك المقاطع ويستشهد بها. وإذا لم تُجب المستندات أو لم تجتز إجابتها الفحص، يجيب نموذج مجاني عبر الإنترنت بدلًا منه، ويُنتقل إلى التالي إن كان أحدها مشغولًا.",
  "html.arch.s4.t": "فحص الحارس",
  "html.arch.s4.d": "تُوزن كل جملة بإشارات مستقلة: تطابق الكلمات، والأرقام والتواريخ والأسماء، والتشابه في المعنى، والاستلزام، ونموذج لكشف الهلوسة. ويجمعها نموذج دمج مدرَّب، ويحدد كاشف على مستوى الكلمة الكلمات الخاطئة بدقة.",
  "html.arch.s5.t": "رأي ثانٍ",
  "html.arch.s5.d": "في الصور والتسجيلات، يقرأ نموذج مجاني عبر الإنترنت الملف نفسه مرة أخرى. ويقارن الحارس القراءتين جملةً جملة ويُظهر مواضع الاتفاق والاختلاف.",
  "html.arch.s6.t": "الحكم",
  "html.arch.s6.d": "موثّقة أو مختلَقة، مع مستوى الخطر والأجزاء المشكوك فيها والأسباب؛ ويُصنَّف كل مصدر مؤيدًا أو مناقضًا أو غير ذي صلة أو غير موجود. وفي اختبار RAGTruth المقفل حقق الحارس AUROC بقيمة 0.856، مقابل 0.687 لأفضل خط أساس.",
  "html.arch.local": "محلي · دون اتصال",
  "html.arch.online": "عبر الإنترنت · مجاني",
  "html.guard.ready": "الحارس · جاهز",
  "html.guard.loading": "الحارس · جارٍ التحميل…",
  "html.guard.failed": "الحارس · تعذّر التحميل",
  "html.local.partly": "دون اتصال · بعض النماذج مفقودة",
  "html.local.none": "دون اتصال · النماذج مفقودة",
  "html.ag.heading": "الشيفرة، عقدة بعقدة",
  "html.ag.lead": "خريطة حية لشيفرة حارس الحقيقة. اختر جزءًا: كل دائرة خضراء وحدة، وكل دائرة خوخية إحدى دوالّها، والأثقل أقرب إلى المركز. مرّر المؤشر على عقدة لترى اسمها، وانقر عليها لترى ما تفعله ومدخلاتها ومخرجاتها وشيفرتها الحقيقية. كبّر بعجلة الفأرة، وحرّك بالسحب، وانقر مرتين على الخلفية لفتح الرسم الذي يشرح هذا الرسم.",
  "html.ag.tab.guardian": "الحارس",
  "html.ag.tab.answers": "الإجابات وعبر الإنترنت",
  "html.ag.tab.readers": "قارئات الصوت والصورة",
  "html.ag.t.guardian": "الحارس: كيف تُفحص الإجابة",
