  "html.ag.core": "نقطة الدخول",
  "html.ag.hint": "العجلة: تكبير · السحب: تحريك · نقر مزدوج على الخلفية: الرسم الفوقي",
  "html.ag.hintMeta": "العجلة: تكبير · السحب: تحريك · نقر مزدوج: إعادة الضبط",
  "html.ag.in": "المدخلات",
