  "html.ag.code": "الشيفرة",
  "html.ag.noCode": "# مجموعة دوالّ: افتح كل واحدة لترى شيفرتها.",
  "html.ag.g0": "عقل تطبيق الويب: يحمّل النماذج المحفوظة مرة واحدة ويهيّئها ويشغّل فحصًا واحدًا في كل مرة. كل إجابة من المحادثة أو RAG أو الواجهة البرمجية تمرّ به.",
  "html.ag.g_lang": "يتعرّف على لغة كل نص، لتذهب كل إجابة إلى فحص يستطيع قراءتها.",
  "html.ag.g_detect": "يحدّد لغة النص من خطّه وكلماته.",
  "html.ag.g_route": "يقرّر أي فحص يقرأ الإجابة: المحرّك الإنجليزي أو الفحص متعدد اللغات أو لا شيء.",
  "html.ag.g_ret": "يجد لكل جملة من الإجابة جمل المصادر الأرجح أن تدعمها.",
  "html.ag.g_rrf": "يدمج ترتيب الكلمات (BM25) وترتيب المعنى (المتجهات) بدمج الرتب المتبادل ويحتفظ بأفضل خمس.",
  "html.ag.g_bm25": "BM25 على جمل المصادر: مدى ورود كلمات الجملة في كل منها.",
  "html.ag.g_sig": "يحسب الإشارات المستقلة التي يقرؤها نموذج الدمج لكل جملة.",
  "html.ag.g_hhem": "نموذج الهلوسة من Vectara (HHEM): مدى اتساق الجملة مع أدلتها.",
  "html.ag.g_detsig": "الكاشف المدرَّب على مستوى الكلمة: احتمال أن تكون كل كلمة مختلَقة، لتحديد الكلمات بدقة.",
  "html.ag.g_sym": "يتحقق من أن الأرقام والأوقات والأسماء في الإجابة واردة في المصادر أو السؤال.",
  "html.ag.g_check": "يشغّل الفحوص الرمزية على كل جمل الإجابة.",
  "html.ag.g_unm": "يسرد الأرقام والأوقات والأسماء في النص التي لا تحتويها الأدلة.",
  "html.ag.g_fus": "نموذج الدمج: مصنِّفات مكدّسة للجملة والإجابة فوق كل الإشارات، معايَرة إلى درجة خطر.",
  "html.ag.g_ens": "يأخذ متوسط الانحدار اللوجستي وتعزيز التدرج: البسيط يعمّم والقوي يرتّب بدقة.",
  "html.ag.g_platt": "يحوّل الدرجة الخام إلى احتمال معايَر دون تغيير الترتيب.",
  "html.ag.g_pipe": "التحليل الحي لإجابة واحدة: الإشارات والتقييم والقواعد الحاكمة والتقرير.",
  "html.ag.g_an": "يفحص إجابة واحدة من البداية إلى النهاية ويعيد تقريرها الكامل.",
  "html.ag.g_contrib": "كم ينخفض خطر الإجابة دون كل جملة، لإظهار الجملة التي تحمل الخطأ.",
  "html.ag.g_multi": "فحص الإجابات بالعربية والصينية والفرنسية والروسية والإسبانية.",
  "html.ag.g_msig": "يبني إشارات هذا الفحص: كلمات المحتوى والأرقام والاستلزام متعدد اللغات.",
  "html.ag.g_mnli": "الاستلزام متعدد اللغات (mDeBERTa): هل تستلزم الأدلة الجملة أم تتركها مفتوحة أم تناقضها.",
  "html.ag.g_exp": "يشرح كل جملة مُعلَّمة: نوع الهلوسة والكلمات الدقيقة وسببًا يفهمه الإنسان.",
  "html.ag.g_expl": "يكتب النوع والمقاطع والسبب لجملة مُعلَّمة واحدة.",
  "html.ag.g_split": "يقسّم الجملة إلى ادعاءاتها المنفصلة بتحليل الاعتماد النحوي، دون نموذج لغوي.",
  "html.ag.g_rep": "التقرير الذي تتلقاه كل واجهة: الحكم وكل ادعاء وأدلته والإصلاحات والضمانات.",
  "html.ag.g_build": "يجمع التقرير من مخرجات كل إشارة وإصلاحات كل جملة.",
  "html.ag.g_conf": "يحدّد عتبات الإنذار بالتنبؤ المطابق المقسَّم، مع معدّل إغفال مُعلَن.",
  "html.ag.g_heal": "الإصلاح الذاتي: يحوّل نتائج التقرير إلى إجابة مصحَّحة ويفحصها مجددًا.",
  "html.ag.g_healf": "يصحّح الإجابة من تقريرها ويشغّل الفحص على النتيجة.",
  "html.ag.g_attr": "يجد الادعاء الذي يخفض حذفُه الخطرَ أكثر من غيره.",
  "html.ag.g_trace": "يجد خطوة الوكيل التي دخلت فيها الهلوسة أول مرة إلى تشغيله.",
  "html.ag.g_tr": "نموذجان مدرَّبان على أدلة الخطوات: أي خطوة هي المنشأ، وهل هناك خطأ أصلًا.",
  "html.ag.g_live": "يراقب الوكيل أثناء تشغيله وينذر قبل أن تصل الهلوسة إلى الإجابة.",
  "html.ag.a0": "يجيب عن السؤال من المكتبة ويفحص الإجابة قبل عرضها.",
  "html.ag.a_lib": "مكتبة المستندات: ملفات الشخص ومستندات المشروع، مقسّمة إلى مقاطع ومحوّلة إلى متجهات مرة واحدة.",
  "html.ag.a_library": "يحفظ المستندات ويجد أقرب المقاطع إلى السؤال.",
  "html.ag.a_fuse": "يدمج ترتيبي الكلمات والمعنى؛ المقطع الذي لا يشارك السؤال أي كلمة لا ينال رتبة كلمات.",
