  "team.title": "团队",
  "team.lead": "Truth Guardian 背后的人：我们的老师兼指导，以及四位团队成员。选择一张卡片，了解每个人。",
  "team.supervisor": "老师兼指导",
  "team.member": "团队成员",
  "team.more": "了解更多",
  "team.close": "关闭",
  "team.role.hamed": "专业工程师、人工智能程序员",
  "team.role.models": "项目已训练模型的设计与训练",
  "team.role.sepehr": "咨询、协调与 UI/UX 设计",
  "team.role.majid": "模型同步与 UI/UX 设计",
  "team.bio.hamed": "团队在本次竞赛中的老师兼指导；专业工程师、人工智能程序员，指导团队完成挑战 4 的工作。",
  "team.bio.models": "负责本项目已训练模型的设计与训练：核查的各项信号如何合成一个风险值，该模型如何训练，以及如何在它从未见过的回答上进行衡量。",
  "team.bio.sepehr": "为团队提供咨询与协调，并负责 UI/UX 设计：页面如何呈现核查结果，让人一眼读懂。",
  "team.bio.majid": "负责项目模型的同步与 UI/UX 设计：文本、声音和图像模型如何在一个引擎中协同工作，页面又如何清楚地呈现它们。",
  "about.title": "关于 Truth Guardian",
  "about.lead": "Truth Guardian 是我们参加 iWISE 2026 人工智能挑战 4（幻觉检测）的作品：一个守护者，把 AI 的回答与其证据放在一起阅读，找出证据不支持的词语，说明原因，并尽可能加以修正。",
  "about.challengeTitle": "挑战",
  "about.challengeBody": "AI 系统即使出错也能流畅作答。本挑战要判断回答是以检索到的文档为依据还是存在幻觉、风险有多大、哪些部分可疑以及依据什么证据，无论是单个回答还是多步智能体。Truth Guardian 首先针对文本做到这一点；作为项目自己的扩展，它还能根据来源纠正被标记的回答，并根据录音中说的内容或图片中写的文字，核查关于录音或图片的回答。",
  "about.engineTitle": "引擎如何工作",
  "about.engineBody": "对于依据文本来源写成的回答，五个阶段在这台计算机上依次运行。每个阶段都会补充证据供下一阶段使用，每一个判定都可以追溯到导致它的词语。",
  "about.s1.label": "证据",
  "about.s1.title": "为每个句子找到证据",
  "about.s1.sub": "回答中的每个句子都会与可能支持它的来源段落匹配，既按关键词（BM25）也按语义，再按排名融合。",
  "about.s2.label": "信号",
  "about.s2.title": "用四种方式阅读",
  "about.s2.sub": "词语重合；逐一核对数字、名称和日期；语义相似度；以及 HHEM，一个专门判断事实一致性的模型。",
  "about.s3.label": "融合",
  "about.s3.title": "汇成一个经过校准的风险值",
  "about.s3.sub": "学习得到的集成模型为每个句子和整个回答权衡这些信号；它的风险值可以当作概率来读。",
  "about.s4.label": "规则",
  "about.s4.title": "捕捉模型遗漏的问题",
  "about.s4.sub": "经 NLI 确认的否定与反义、角色互换、夸大其词、相互矛盾的来源，以及指向别处的引用。",
  "about.s5.label": "报告",
  "about.s5.title": "解释、修正、保证",
  "about.s5.sub": "确切的词语、证据、取自来源的修正、责任归属、遗漏的内容、统计保证、分诊通道和等级。",
  "about.runsTitle": "处理在哪里进行",
  "about.runsBody": "一切都在一台普通笔记本电脑的处理器上运行，无需显卡，也无需联网。语言模型保存在项目文件夹内，其中最重的模型通过 ONNX Runtime 运行，重复出现的句子直接从缓存中取得结果，因此一次核查只需几秒钟。任何回答或来源都不会离开这台计算机。",
  "contact.title": "联系我们",
  "contact.lead": "有问题、建议或需要报告的故障？请写信给 Truth Guardian 团队；您的消息会直接送达我们的邮箱，我们会通过电子邮件回复。",
