  "card.short.summary": "摘要",
  "card.limit1": "在 RAGTruth（英文新闻、问答和商业数据）上训练和校准。在其他领域排序效果较弱（锁定的 HaluEval 对话 0.67、摘要 0.69 AUROC，校准误差约 0.23），直到用几十个已标注回答拟合领域配置；用 50 个回答时，在配置未见过的回答上，对话升至约 0.72，摘要升至 0.79，校准误差降至约 0.07。",
  "card.limit2": "仍有部分编辑能蒙混过关：反义词被识破 45%，更强的数量词 57%，被删去的保留语 37%（D-114 之前分别为 37% 和 20%）。",
  "card.limit3": "在真实的智能体运行（AgentHallu）上，实时守护者的任何设置都无法很好地区分忠实与产生幻觉的智能体（锁定测试上检测 AUROC 约 0.53）；在折外尝试的三项修正都没有带来改变（D-116）。找出出错步骤的效果好于随机，但不可靠。",
  "card.limit4": "锁定 RAGTruth 测试上的 span F1（0.30）低于 dev（0.38）：对整个回答的结论比错误的确切位置更稳定。训练好的检测器给出的精确词语把 dev 上的 span F1 提升到 0.41；为测量它并未再次打开锁定测试。",
  "card.limit5": "修复的改动大多正确，但并非总是如此：使用修复后的回答前请先阅读改动。",
  "card.limit6": "它只对照给定的来源核查回答。一个在现实中为真、但来源中没有的陈述会被算作无依据。",
