  "card.calibTitle": "风险 0.8 就意味着 80% 吗？预测风险与回答实际存在幻觉的频率对比",
  "card.calib1": "落在虚线上的点意味着风险可以当作概率来读：在风险接近 0.8 的回答中，约 80% 确实存在幻觉。点在线下方表示风险偏高（偏谨慎）；在线上方则偏低。",
  "card.calib2": "在模型校准所用的 RAGTruth 上，无论 dev 还是锁定测试，点都紧贴虚线。在测试集上量表中段略偏高，因此守护者在那里偏于谨慎。",
  "card.calib3": "在从未见过的 HaluEval 领域，低风险偏低、高风险偏高。因此要先用新领域几十个已标注回答拟合领域配置，重新校准风险，再在那里使用各项保证。",
  "card.calibNote": "十个等宽风险区间，与所报告的校准误差（ECE）相同。将鼠标悬停在点上可查看数值。",
