  "html.free.n.opinion": "这个回答依据的是图像模型说它看到的内容，那是它的看法，所以不以此核查；只有回答所说图中的文字，会对照独立读取器读到的内容核查。",
  "html.second.title.image": "第二意见：另一个模型看了同一张图像（{m}）",
