  "html.second.caution": "两个模型一致并不是证明，只是降低出错的可能。两者不一致时，至少有一个是错的。",
  "html.seen.disputed": "两个模型对图中文字的读法不同：很可能是幻觉",
  "html.seen.st.agreed": "两个模型都读到",
  "html.seen.st.disputed": "读法不同",
  "html.seen.r.second_read": "读取器没有读到文字，但第二个模型也读到了这些词",
  "html.seen.r.second_differs": "读取器没有读到文字，第二个模型读到的是别的内容",
  "html.lead": "真相守护者会在你采信 AI 的回答之前先核查它。文本会逐句与你的文档或守护者自行找到的来源（维基百科、维基数据、网络搜索、学术文献）比对，每个来源都标明是支持、反驳还是无关。图片和录音先由本地模型读取，再由免费的在线模型重新读取，并比较两次读取的结果。每次核查都给出明确结论：有据可依或属于幻觉，并附风险程度和理由；本地模型可离线工作，联网时在线核查随之加入。",
  "html.online.checking": "在线 · 正在检查…",
  "html.online.on": "在线 · 模型已连接",
  "html.online.partly": "在线 · 部分连接",
  "html.online.off": "在线 · 未连接",
  "html.online.restart": "在线 · 请重启服务器",
  "html.arch": "系统架构",
  "html.arch.lead": "模型与守护者如何协同工作，从读取文件到给出结论：共六个阶段；本地阶段在这台电脑上离线运行，在线阶段免费，仅在联网时使用。",
  "html.arch.s1.t": "读取输入",
  "html.arch.s1.d": "录音被转写成文字并识别每段的语言，图片中的文字被读出，图片内容被描述；全部在这台电脑上完成。",
  "html.arch.s2.t": "查找证据",
  "html.arch.s2.d": "通过把词语匹配与语义相似度融合，从你的文档中找出最相关的段落。在线时，守护者会自行查找来源，而不是轻信模型给出的来源。",
  "html.arch.s3.t": "撰写回答",
  "html.arch.s3.d": "本地模型根据这些段落撰写回答并标注引用。如果文档无法回答，或其回答未通过核查，则改由免费的在线模型回答；某个模型繁忙时依次换用下一个。",
  "html.arch.s4.t": "守护者核查",
  "html.arch.s4.d": "每句话都由多个独立信号衡量：词语重合、数字日期与人名、语义相似度、蕴含关系以及幻觉检测模型。经过训练的融合模型综合这些信号，词级检测器精确标出出错的词。",
  "html.arch.s5.t": "第二意见",
  "html.arch.s5.d": "对于图片和录音，免费的在线模型会再次读取同一文件。守护者逐句比较两次读取，标出一致与不一致之处。",
  "html.arch.s6.t": "结论",
  "html.arch.s6.d": "有据可依或属于幻觉，并给出风险、可疑部分和理由；每个来源被标为支持、反驳、无关或未找到。在 RAGTruth 锁定测试集上，守护者的 AUROC 为 0.856，最佳基线为 0.687。",
  "html.arch.local": "本地 · 离线",
  "html.arch.online": "在线 · 免费",
  "html.guard.ready": "守护者 · 就绪",
  "html.guard.loading": "守护者 · 正在加载…",
  "html.guard.failed": "守护者 · 加载失败",
  "html.local.partly": "离线 · 部分模型缺失",
  "html.local.none": "离线 · 模型缺失",
  "html.ag.heading": "代码，逐个节点",
  "html.ag.lead": "真相守护者代码的实时地图。选择一个部分：每个绿色圆圈是一个模块，每个桃色圆圈是它的一个函数，越重要越靠近中心。将指针悬停在节点上可看到名称；点击可查看它的作用、输入输出和真实代码。滚轮缩放，拖动移动，双击背景可打开解释此图本身的图。",
  "html.ag.tab.guardian": "守护者",
  "html.ag.tab.answers": "回答与在线",
  "html.ag.tab.readers": "声音与图像读取器",
  "html.ag.t.guardian": "守护者：如何核查一个回答",
  "html.ag.s.guardian": "src/truth_guardian · 点击节点查看代码",
