  "team.title": "Équipe",
  "team.lead": "Les personnes derrière Truth Guardian : notre enseignant et guide, et les quatre membres de l'équipe. Choisissez une carte pour en savoir plus.",
  "team.supervisor": "Enseignant et guide",
  "team.member": "Membre de l'équipe",
  "team.more": "En savoir plus",
  "team.close": "Fermer",
  "team.role.hamed": "Ingénieur spécialisé et programmeur en IA",
  "team.role.models": "Conception et entraînement des modèles du projet",
  "team.role.sepehr": "Conseil, coordination et design UI/UX",
  "team.role.majid": "Synchronisation des modèles et design UI/UX",
  "team.bio.hamed": "Enseignant et guide de l'équipe pour ces compétitions ; ingénieur spécialisé et programmeur en IA, il guide le travail de l'équipe sur le défi 4.",
  "team.bio.models": "Travail sur la conception et l'entraînement des modèles de ce projet : comment les signaux de la vérification se combinent en un seul risque, comment ce modèle est entraîné et comment il est mesuré sur des réponses qu'il n'a jamais vues.",
  "team.bio.sepehr": "Conseil et coordination de l'équipe, et design UI/UX : comment les pages présentent le résultat d'une vérification pour qu'il se lise d'un coup d'œil.",
  "team.bio.majid": "Synchronisation des modèles du projet et design UI/UX : comment les modèles du texte, du son et des images fonctionnent ensemble dans un seul moteur, et comment les pages les présentent clairement.",
  "about.title": "À propos de Truth Guardian",
  "about.lead": "Truth Guardian est notre participation au défi IA n° 4 d’iWISE 2026 sur la détection des hallucinations : un gardien qui lit la réponse d’une IA à côté de ses preuves, trouve les mots que les preuves n’appuient pas, explique pourquoi et corrige ce qu’il peut.",
  "about.challengeTitle": "Le défi",
  "about.challengeBody": "Les systèmes d'IA répondent avec aisance même quand ils se trompent. Le défi consiste à dire si une réponse est fondée sur les documents récupérés ou hallucinée, quel est le risque, quelles parties sont suspectes et sur quelles preuves, pour une réponse seule comme pour un agent à plusieurs étapes. Truth Guardian le fait d'abord pour le texte et, en ajouts propres au projet, corrige une réponse signalée à partir de ses sources et vérifie aussi les réponses sur un enregistrement ou une image par rapport à ce qui y est dit ou écrit.",
  "about.engineTitle": "Comment fonctionne le moteur",
  "about.engineBody": "Pour une réponse rédigée à partir de sources textuelles, cinq étapes s’enchaînent sur cet ordinateur. Chacune ajoute des preuves que la suivante utilise, et chaque verdict peut être retracé jusqu’aux mots qui l’ont provoqué.",
  "about.s1.label": "Preuves",
  "about.s1.title": "Trouver des preuves pour chaque phrase",
  "about.s1.sub": "Chaque phrase de la réponse est rapprochée des passages des sources qui pourraient l'étayer, par mots-clés (BM25) et par le sens, puis fusionnés par rang.",
  "about.s2.label": "Signaux",
  "about.s2.title": "La lire de quatre manières",
  "about.s2.sub": "Mots communs ; nombres, noms et dates contrôlés un par un ; similarité de sens ; et HHEM, un modèle entraîné à juger la cohérence factuelle.",
  "about.s3.label": "Fusion",
  "about.s3.title": "En faire un seul risque calibré",
  "about.s3.sub": "Un ensemble appris pondère les signaux pour chaque phrase et pour toute la réponse ; son risque se lit comme une probabilité.",
  "about.s4.label": "Règles",
  "about.s4.title": "Repérer ce que les modèles manquent",
  "about.s4.sub": "Négations et contraires confirmés par NLI, rôles inversés, exagérations, sources divergentes, citations qui renvoient ailleurs.",
  "about.s5.label": "Rapport",
  "about.s5.title": "Expliquer, corriger, garantir",
  "about.s5.sub": "Mots exacts, preuves, correction tirée des sources, responsable, ce qui a été omis, garantie statistique, file de tri et note.",
  "about.runsTitle": "Où se fait le traitement",
  "about.runsBody": "Tout s’exécute sur le processeur d’un ordinateur portable ordinaire, sans carte graphique ni connexion à Internet. Les modèles de langue sont conservés dans le dossier du projet, le plus lourd s’exécute avec ONNX Runtime, et les phrases déjà vues sont reprises d’un cache : une vérification prend quelques secondes. Aucune réponse ni source ne quitte l’ordinateur.",
  "contact.title": "Nous contacter",
  "contact.lead": "Une question, une suggestion ou un problème à signaler ? Écrivez à l’équipe Truth Guardian ; votre message arrive directement dans notre boîte et nous répondons par e-mail.",
  "contact.name": "Votre nom",
