  "tour.s1.title": "Bienvenue dans Truth Guardian",
  "tour.s1.body": "Il vérifie une réponse d'IA par rapport aux sources qui lui ont été fournies, affirmation par affirmation, explique chaque alerte et corrige ce qu'il peut, entièrement sur cet ordinateur. Cette visite dure environ trois minutes. Utilisez les flèches ou les boutons ; Échap pour quitter.",
