  "models.title": "Les modèles derrière cette entrée",
  "models.lead.audio": "Un enregistrement est transcrit sur cet ordinateur par Whisper Small : chaque passage avec son moment, sa langue et le degré de certitude du modèle.",
  "models.lead.image": "Le texte d’une image est lu par Tesseract, l’écriture d’abord puis ses langues probables ; ce que montre l’image est décrit par Qwen3-VL, un avis toujours soumis à une vérification humaine.",
  "models.role.speech": "Parole en texte",
  "models.role.ocr": "Texte dans les images",
  "models.role.vision": "Ce que montre une image",
  "models.about.speech": "Tourne sur le processeur de cet ordinateur (CTranslate2, 8 bits). La langue est reconnue passage par passage ; le silence ne donne aucun mot et part en vérification.",
  "models.about.ocr": "Tesseract 5.5 avec les modèles rapides de 163 langues et écritures : il trouve d’abord l’écriture et n’essaie que les quelques langues qui l’emploient.",
  "models.about.vision": "Qwen3-VL-2B via llama.cpp, lancé sur cet ordinateur à la première question. Sa réponse est un avis, jamais une preuve.",
