  "models.note": "« Exécuté sur des échantillons » signifie que chaque lecteur a correctement lu des images et des enregistrements fabriqués ici au contenu connu ; cela ne dit pas sa qualité sur de vraies photos et de vraies voix, qui demande des données réelles annotées, pas encore mesurée.",
