  "card.locked5": "Ce sont les résultats du système tel qu'il était alors (D-109). Les changements ultérieurs (profils de domaine, mots exacts, règles d'exagération : D-113 à D-115) sont mesurés sur les seules données de développement ; les jeux verrouillés n'ont pas été rouverts.",
