  "example.halueval-dialogue-4203-hallucinated.about": "Случайно выбран из HaluEval dialogue (внешний dev), это область, не похожая на RAGTruth; проверен с профилем HaluEval dialogue, настроенным на 50 других размеченных ответах.",
