  "example.halueval-dialogue-6865-grounded.about": "Случайно выбран из HaluEval dialogue (внешний dev), это область, не похожая на RAGTruth; проверен с профилем HaluEval dialogue, настроенным на 50 других размеченных ответах.",
  "models.title": "Модели за этим входом",
  "models.lead.audio": "Запись превращается в текст на этом компьютере моделью Whisper Small: каждый фрагмент со своим временем, языком и степенью уверенности модели.",
  "models.lead.image": "Текст на изображении читает Tesseract: сначала письменность, затем её вероятные языки; то, что показано на изображении, описывает Qwen3-VL — это мнение, которое всегда идёт на проверку человеку.",
  "models.role.speech": "Речь в текст",
  "models.role.ocr": "Текст на изображениях",
  "models.role.vision": "Что показано на изображении",
  "models.about.speech": "Работает на процессоре этого компьютера (CTranslate2, 8 бит). Язык определяется для каждого фрагмента; тишина не даёт слов и отправляется на проверку.",
  "models.about.ocr": "Tesseract 5.5 с быстрыми моделями для 163 языков и письменностей: сначала находит письменность и пробует лишь несколько языков, которые на ней пишутся.",
  "models.about.vision": "Qwen3-VL-2B через llama.cpp, запускается на этом компьютере при первом вопросе. Его ответ — мнение, а не доказательство.",
  "models.files": "Файлы модели на месте",
