  "models.note": "«Запущено на образцах» значит, что каждое средство чтения верно прочитало изображения и записи с известным содержимым, сделанные здесь; это не говорит о качестве на настоящих фото и голосах. Для этого нужны размеченные реальные данные, которые ещё не измерены.",
