  "card.short.dialogue": "Диалог",
  "card.short.summary": "Реферат",
  "card.limit1": "Обучен и откалиброван на RAGTruth (новости, вопрос-ответ и деловые данные на английском). В другом домене ранжирование держится хуже (закрытый HaluEval: диалог 0,67 и реферирование 0,69 по AUROC, ошибка калибровки около 0,23), пока не подобран профиль домена на нескольких десятках размеченных ответов; с 50 ответами на не виденных профилем данных диалог поднимается примерно до 0,72, реферирование до 0,79, а ошибка калибровки падает примерно до 0,07.",
  "card.limit2": "Некоторые правки всё ещё проходят: противоположное слово распознаётся в 45% случаев, более сильный квантор — в 57%, удалённая оговорка — в 37% (против 37% и 20% до D-114).",
  "card.limit3": "На реальных запусках агентов (AgentHallu) ни одна настройка стража не разделяет корректных и галлюцинирующих агентов хорошо (AUROC обнаружения около 0,53 на закрытом тесте); три исправления, опробованные вне фолда, ничего не изменили (D-116). Поиск ошибочного шага работает лучше случайного, но ненадёжно.",
  "card.limit4": "Span F1 на закрытом тесте RAGTruth (0,30) ниже, чем на dev (0,38): вердикт для всего ответа держится лучше, чем точное место ошибки. Точные слова от обученного детектора поднимают span F1 на dev до 0,41; закрытый тест для этого повторно не открывался.",
  "card.limit5": "Правки при исправлении часто верны, но не всегда: прочитайте изменения перед использованием исправленного ответа.",
  "card.limit6": "Он сверяет ответы только с переданными источниками. Утверждение, верное в реальности, но отсутствующее в источниках, считается неподтверждённым.",
  "card.title": "Надёжность",
  "card.lead": "Каждое число на этой странице прочитано из сохранённых в проекте файлов оценки. Пороги выбраны на обучающих или dev-данных; закрытый тестовый набор открывается один раз, в самом конце.",
