  "card.unseenLockedNote": "Ответов на задачу: {n}, открыт один раз, без подстройки на HaluEval; пороги взяты от RAGTruth, поэтому риск здесь откалиброван хуже. Обучение: {t} ответов RAGTruth.",
  "card.unseen": "На данных, которых он никогда не видел (HaluEval, AUROC)",
  "card.unseenNote": "Ответов на задачу: {n}, без подстройки на HaluEval. Обучение: {t} ответов RAGTruth, AUROC вне фолда {a}.",
  "card.calibTitle": "Риск 0,8 — это 80%? Предсказанный риск против того, как часто ответы действительно содержали галлюцинации",
  "card.calib1": "Точка на пунктирной линии означает, что риск можно читать как вероятность: из ответов с риском около 0,8 примерно 80% содержали галлюцинации. Точки ниже линии — риск завышен (осторожно); выше — занижен.",
  "card.calib2": "На RAGTruth, где модель калибровалась, точки держатся близко к линии — и на dev, и на закрытом тесте. На тесте середина шкалы немного завышена, так что там страж перестраховывается.",
  "card.calib3": "На HaluEval, незнакомом домене, низкие риски слишком низкие, а высокие — слишком высокие. Поэтому профиль домена, подобранный на нескольких десятках размеченных ответов нового домена, перекалибрует риск, прежде чем там использовать гарантии.",
  "card.calibNote": "Десять интервалов риска одинаковой ширины — те же, что и для указанной ошибки калибровки (ECE). Наведите на точку, чтобы увидеть числа.",
  "card.profilesTitle": "Новый домен по {n} размеченным ответам: прилагаемые профили домена, проверенные на не виденных ими ответах",
  "card.colProfile": "Профиль",
  "card.colChecked": "Проверено ответов",
  "card.colAurocArrow": "AUROC, модель → профиль",
  "card.colCalib": "Ошибка калибровки",
  "card.colVerdictAcc": "Точность вердикта",
  "card.profilesNote": "Каждый профиль перевзвешивает риск модели и три сигнала доказательств, усреднённых по предложениям ответа, перекалибрует риск и задаёт собственные линии гарантии и вердикт домена. Он никогда не использует длину ответа: на HaluEval одна длина разделяет метки{alone} — лазейка, которой нет ни в одном реальном домене. HaluEval external dev; закрытые наборы HaluEval не использовались.",
