  "nav.audioRead": "Habla o sube una grabación",
  "nav.imageRead": "Leer una imagen",
  "nav.models": "Modelos y su estado",
  "team.title": "Equipo",
  "team.lead": "Las personas detrás de Truth Guardian: nuestro profesor y guía, y los cuatro miembros del equipo. Elige una tarjeta para saber más.",
  "team.supervisor": "Profesor y guía",
  "team.member": "Miembro del equipo",
  "team.more": "Leer más",
  "team.close": "Cerrar",
  "team.role.hamed": "Ingeniero especialista y programador de IA",
  "team.role.models": "Diseño y entrenamiento de los modelos del proyecto",
  "team.role.sepehr": "Asesoría, coordinación y diseño UI/UX",
  "team.role.majid": "Sincronización de modelos y diseño UI/UX",
  "team.bio.hamed": "Profesor y guía del equipo en estas competiciones; ingeniero especialista y programador de IA, orienta el trabajo del equipo en el reto 4.",
  "team.bio.models": "Trabajo en el diseño y el entrenamiento de los modelos de este proyecto: cómo las señales de la verificación se combinan en un solo riesgo, cómo se entrena ese modelo y cómo se mide con respuestas que nunca ha visto.",
  "team.bio.sepehr": "Asesoría y coordinación del equipo, y diseño UI/UX: cómo las páginas presentan el resultado de una verificación para que se lea de un vistazo.",
  "team.bio.majid": "Sincronización de los modelos del proyecto y diseño UI/UX: cómo los modelos de texto, sonido e imagen funcionan juntos en un solo motor, y cómo las páginas los presentan con claridad.",
  "about.title": "Acerca de Truth Guardian",
  "about.lead": "Truth Guardian es nuestra participación en el reto de IA 4 de iWISE 2026 sobre detección de alucinaciones: un guardián que lee la respuesta de una IA junto a sus pruebas, encuentra las palabras que las pruebas no respaldan, explica por qué y corrige lo que puede.",
  "about.challengeTitle": "El reto",
  "about.challengeBody": "Los sistemas de IA responden con soltura incluso cuando se equivocan. El reto es saber si una respuesta se apoya en los documentos recuperados o contiene una alucinación, cuánto riesgo tiene, qué partes son sospechosas y con qué evidencia, tanto para una respuesta como para un agente de varios pasos. Truth Guardian lo hace primero con el texto y, como añadidos propios del proyecto, corrige una respuesta señalada a partir de sus fuentes y también verifica respuestas sobre una grabación o una imagen frente a lo que se dice o está escrito en ellas.",
  "about.engineTitle": "Cómo funciona el motor",
  "about.engineBody": "Para una respuesta escrita a partir de fuentes de texto, cinco etapas se ejecutan una tras otra en este ordenador. Cada etapa añade pruebas que usa la siguiente, y cada veredicto puede rastrearse hasta las palabras que lo causaron.",
  "about.s1.label": "Evidencia",
  "about.s1.title": "Encontrar evidencia para cada frase",
  "about.s1.sub": "Cada frase de la respuesta se empareja con los pasajes de las fuentes que podrían respaldarla, por palabras clave (BM25) y por significado, combinados por rango.",
  "about.s2.label": "Señales",
  "about.s2.title": "Leerla de cuatro maneras",
  "about.s2.sub": "Palabras en común; números, nombres y fechas uno por uno; similitud de significado; y HHEM, un modelo entrenado para juzgar la coherencia factual.",
  "about.s3.label": "Fusión",
  "about.s3.title": "Convertirlas en un único riesgo calibrado",
  "about.s3.sub": "Un conjunto aprendido pondera las señales para cada frase y para toda la respuesta; su riesgo se lee como una probabilidad.",
  "about.s4.label": "Reglas",
  "about.s4.title": "Atrapar lo que los modelos pasan por alto",
  "about.s4.sub": "Negaciones y opuestos confirmados por NLI, papeles invertidos, exageraciones, fuentes en desacuerdo y citas que apuntan a otro sitio.",
  "about.s5.label": "Informe",
  "about.s5.title": "Explicar, corregir, garantizar",
  "about.s5.sub": "Palabras exactas, evidencia, una corrección de las fuentes, el culpable, lo que se omitió, una garantía estadística, un carril de triaje y una nota.",
  "about.runsTitle": "Dónde se hace el procesamiento",
  "about.runsBody": "Todo se ejecuta en el procesador de un portátil corriente, sin tarjeta gráfica ni conexión a Internet. Los modelos de lenguaje se guardan dentro de la carpeta del proyecto, el más pesado se ejecuta con ONNX Runtime y las frases repetidas se toman de una caché, así que una verificación tarda unos segundos. Ninguna respuesta ni fuente sale del ordenador.",
  "contact.title": "Contacto",
  "contact.lead": "¿Una pregunta, una sugerencia o un problema que comunicar? Escribe al equipo de Truth Guardian; tu mensaje llega directamente a nuestro correo y respondemos por email.",
