  "agent.lead": "Los pasos llegan uno a uno, y cada uno se verifica solo con la pregunta y las salidas de herramientas anteriores. Cuando un pensamiento afirma un hecho que ninguna herramienta devolvió, o el agente sigue tras el fallo de una herramienta, el guardián detiene la ejecución antes de que la respuesta errónea llegue a nadie.",
