  "agent.measuredTitle": "Cómo rinde el guardián en vivo (medido, 220 ejecuciones de TG-Agent dev)",
  "agent.measured": "Estricta: detiene el {a} de las ejecuciones con alucinación y el {b} de las fieles; cuando detiene, el {c} de las detenciones cae en el paso defectuoso. Flexible: detiene el {d} y nunca una ejecución fiel ({e}).",
  "card.seriesDev": "RAGTruth dev",
  "card.seriesTest": "RAGTruth test (bloqueado)",
  "card.seriesHalu": "HaluEval (bloqueado, dominio no visto)",
  "card.task.qa": "Preguntas y respuestas",
  "card.task.dialogue": "Diálogo",
  "card.task.summary": "Resumen",
  "card.short.qa": "QA",
  "card.short.dialogue": "Diálogo",
  "card.short.summary": "Resumen",
  "card.limit1": "Entrenado y calibrado con RAGTruth (noticias, preguntas y respuestas y datos empresariales en inglés). En otro dominio la ordenación aguanta peor (HaluEval bloqueado: diálogo 0,67 y resumen 0,69 de AUROC, error de calibración de alrededor de 0,23) hasta que se ajusta un perfil de dominio con unas decenas de respuestas etiquetadas; con 50, el diálogo sube a cerca de 0,72 y el resumen a 0,79 en respuestas que el perfil no vio, y el error de calibración baja a cerca de 0,07.",
  "card.limit2": "Algunas ediciones todavía se cuelan: una palabra opuesta se detecta el 45 % de las veces, un cuantificador más fuerte el 57 % y una cautela eliminada el 37 % (frente al 37 % y 20 % antes de D-114).",
  "card.limit3": "En ejecuciones reales de agentes (AgentHallu), ningún ajuste del guardián en vivo separa bien a los agentes fieles de los que alucinan (AUROC de detección de cerca de 0,53 en la prueba bloqueada); tres correcciones probadas fuera de pliegue no cambiaron nada (D-116). Encontrar el paso defectuoso funciona mejor que el azar, pero no de forma fiable.",
  "card.limit4": "El span F1 en la prueba bloqueada de RAGTruth (0,30) es menor que en dev (0,38): el veredicto sobre toda la respuesta aguanta mejor que el lugar exacto del error. Las palabras exactas del detector entrenado elevan el span F1 de dev a 0,41; la prueba bloqueada no se ha vuelto a abrir para medirlo.",
  "card.limit5": "Las ediciones de corrección suelen ser acertadas, pero no siempre: lee los cambios antes de usar una respuesta corregida.",
  "card.limit6": "Contrasta las respuestas solo con las fuentes dadas. Una afirmación cierta en el mundo pero ausente de las fuentes cuenta como sin respaldo.",
  "card.title": "Fiabilidad",
  "card.lead": "Cada número de esta página se lee de los archivos de evaluación guardados en el proyecto. Los umbrales se eligieron con datos de entrenamiento o desarrollo; el conjunto de prueba bloqueado se abre una sola vez, al final.",
  "card.versions": "modelo de fusión {m} · rastreador {t}",
