  "card.error": "No se pudo cargar la página de fiabilidad: {e}",
  "card.loading": "Cargando los resultados…",
  "card.lockedTitle": "Conjunto de prueba bloqueado: RAGTruth test, abierto una vez con el modelo final y los umbrales elegidos en dev",
  "card.auroc": "AUROC",
