  "card.devAuroc": "AUROC en RAGTruth dev",
  "card.fusionAlone": "; solo el modelo de fusión {v}",
  "card.baselinesLocked": "Frente a las referencias (RAGTruth test bloqueado, AUROC)",
  "card.lettuce": "LettuceDetect (externo)",
  "card.sameAnswers": "Mismas respuestas, umbrales de dev. En dev: Truth Guardian {a}, mejor referencia {b}.",
  "card.lettuceNote": " LettuceDetect es un detector publicado, ajustado con el propio RAGTruth train, así que esta prueba es su terreno; encuentra mejor las palabras erróneas (span F1 {s}) pero ordena peor las respuestas{halu}.",
  "card.lettuceHalu": "; en HaluEval QA / diálogo / resumen obtiene {v}",
  "card.baselinesDev": "Frente a las referencias (RAGTruth dev, AUROC)",
  "card.unseenLocked": "Con datos que nunca vio (HaluEval bloqueado, AUROC)",
  "card.bestBaseline": "{task}, mejor referencia",
  "card.unseenLockedNote": "{n} respuestas por tarea, abierto una vez, sin ajustes en HaluEval; los umbrales son los de RAGTruth, así que aquí el riesgo está peor calibrado. Entrenamiento: {t} respuestas de RAGTruth.",
  "card.unseen": "Con datos que nunca vio (HaluEval, AUROC)",
  "card.unseenNote": "{n} respuestas por tarea, sin ajustes en HaluEval. Entrenamiento: {t} respuestas de RAGTruth, AUROC fuera de pliegue {a}.",
  "card.calibTitle": "¿Un riesgo de 0,8 significa un 80 %? Riesgo predicho frente a la frecuencia real de alucinación",
  "card.calib1": "Un punto sobre la línea discontinua significa que el riesgo se puede leer como una probabilidad: de las respuestas con un riesgo cercano a 0,8, alrededor del 80 % tenían alucinación. Los puntos por debajo indican un riesgo alto (prudente); por encima, bajo.",
  "card.calib2": "En RAGTruth, donde se calibró el modelo, los puntos se mantienen cerca de la línea, en dev y en la prueba bloqueada. En la prueba, el centro de la escala queda algo alto, así que el guardián peca de prudente ahí.",
  "card.calib3": "En HaluEval, un dominio que nunca vio, los riesgos bajos son demasiado bajos y los altos demasiado altos. Por eso un perfil de dominio, ajustado con unas decenas de respuestas etiquetadas del nuevo dominio, recalibra el riesgo antes de usar allí las garantías.",
  "card.calibNote": "Diez tramos de riesgo de igual anchura, los mismos del error de calibración (ECE) indicado. Pasa el puntero sobre un punto para ver sus números.",
  "card.profilesTitle": "Un dominio nuevo a partir de {n} respuestas etiquetadas: los perfiles de dominio incluidos, probados con respuestas que no vieron",
  "card.colProfile": "Perfil",
  "card.colChecked": "Respuestas verificadas",
  "card.colAurocArrow": "AUROC, modelo → perfil",
  "card.colCalib": "Error de calibración",
  "card.colVerdictAcc": "Exactitud del veredicto",
  "card.profilesNote": "Cada perfil repondera el riesgo del modelo y tres señales de evidencia promediadas sobre las frases de la respuesta, recalibra el riesgo y fija las líneas de garantía y el veredicto propios del dominio. Nunca usa la longitud de la respuesta: en HaluEval la longitud por sí sola separa las etiquetas{alone}, un atajo que ningún dominio real ofrece. HaluEval external dev; no se usaron los conjuntos HaluEval bloqueados.",
  "card.lengthAlone": " (AUROC {list})",
  "card.foolTitle": "Engañar al guardián: una edición controlada por respuesta (372 respuestas dev editadas, 60 controles sin editar)",
  "card.colEdit": "Edición",
  "card.colAnswers": "Respuestas",
  "card.colCaught": "Detectadas",
  "card.colExact": "Lugar exacto encontrado",
  "card.colAurocUnedited": "AUROC frente a sin editar",
  "card.foolNote": "Las respuestas de control sin editar se marcan el {p} de las veces.",
  "card.guaranteeTitle": "Garantías estadísticas (conformes, α = 0,1)",
  "card.guarantee": "En {n} divisiones aleatorias de RAGTruth dev: la línea de captura dejó escapar el {a} de las respuestas con alucinación y la línea de alarma dio un {b} de falsas alarmas, ambas dentro del 10 % prometido.",
  "card.triageTitle": "Carriles de triaje (divisiones reservadas)",
  "card.triage": "El {a} de las respuestas pasa (el {b} de ellas con alucinación, objetivo como máximo 10 %), el {c} va a revisión y el {d} se bloquea (el {e} de ellas con alucinación). El {f} de las alucinaciones nunca pasa.",
  "card.speedTitle": "Velocidad en este portátil (solo CPU)",
  "card.speed": "{m} s por respuesta de media, {p} s en el percentil 95, en {n} respuestas dev una vez preparado. Cargar los modelos lleva unos {c} s al arrancar.",
  "card.agentsTitle": "Agentes: encontrar el paso donde falló",
  "card.agents": "TG-Agent ({n} ejecuciones): AUROC de detección {a}; el paso defectuoso exacto en el {b} de las ejecuciones con alucinación, a un paso como mucho en el {c} (azar {d}).",
  "card.agentsHallu": " AgentHallu ({n} ejecuciones reales): paso exacto {a} (azar {b}), AUROC de detección {c}.",
  "card.healTitle": "Autocorrección (84 respuestas dev)",
  "card.heal": "De las respuestas con alucinación marcadas, el {a} acaba juzgado como fundamentado; el riesgo medio baja de {b} a {c}. Las ediciones eliminan el {d} del texto erróneo anotado con una precisión del {e}; las respuestas fundamentadas pierden el {f} de su texto.",
  "card.limits": "Límites conocidos",
  "card.lockedSets": "Conjuntos de prueba bloqueados",
  "card.locked1": "RAGTruth test: AUROC {a}, F1 {b}, span F1 {c} ({n} respuestas).",
  "card.locked2": "HaluEval (nunca usado para entrenar): AUROC {list}, {n} respuestas cada uno.",
  "card.locked3": "AgentHallu ({n} ejecuciones reales de agentes): paso defectuoso encontrado exactamente en el {a} (azar {b}), AUROC de detección {c}.",
  "card.locked4": "Cada uno se evaluó una sola vez y quedó registrado en eval/locked_runs.log; no se ajustó nada sobre ellos.",
  "card.locked5": "Son los resultados del sistema tal como estaba entonces (D-109). Los cambios posteriores (perfiles de dominio, palabras exactas, reglas de exageración: D-113 a D-115) se miden solo con datos de desarrollo; los conjuntos bloqueados no se volvieron a abrir.",
