  "html.free.n.main": "Respondió un modelo gratuito en línea, porque los documentos no tenían la respuesta. El Guardián la comprobó aquí con las páginas que nombró el modelo y artículos de Wikipedia que encontró él mismo: «fundamentada» significa que la respuesta coincide con lo encontrado, no que cada página sea correcta.",
