  "html.chat.hint": "Para el informe completo del Guardián, pulsa «Truth Guardian check».",
  "html.free.n.local": "La respuesta escrita a partir de los documentos no pasó la comprobación del Guardián, así que la pregunta se hizo en línea.",
  "html.seen.title": "Comprobado con el texto leído en la imagen (Tesseract, un lector aparte)",
  "html.seen.grounded": "El texto que la respuesta dice ver en la imagen se encontró en ella",
  "html.seen.hallucinated": "Alucinación: la respuesta dice que la imagen muestra un texto que no está",
