  "team.title": "تیم",
  "team.lead": "افراد پشت Truth Guardian: استاد و راهنمای ما و چهار عضو تیم. برای خواندن توضیح هر نفر، روی کادرش بزنید.",
  "team.supervisor": "استاد و راهنما",
  "team.member": "عضو تیم",
  "team.more": "بیشتر بخوانید",
  "team.close": "بستن",
  "team.role.hamed": "مهندس متخصص و برنامه‌نویس هوش مصنوعی",
  "team.role.models": "طراحی و آموزش مدل‌های آموزش‌دیدهٔ پروژه",
  "team.role.sepehr": "مشاوره، هماهنگی و طراحی UI/UX",
  "team.role.majid": "همگام‌سازی مدل‌ها و طراحی UI/UX",
  "team.bio.hamed": "استاد و راهنمای تیم در این مسابقات؛ مهندس متخصص و برنامه‌نویس هوش مصنوعی که تیم را در کار روی چالش ۴ راهنمایی می‌کند.",
  "team.bio.models": "در طراحی و آموزش مدل‌های آموزش‌دیدهٔ این پروژه فعالیت کرده است؛ یعنی اینکه نشانه‌های بررسی چطور به یک عدد خطر تبدیل شوند، آن مدل چطور آموزش ببیند و روی پاسخ‌هایی که هرگز ندیده چطور سنجیده شود.",
  "team.bio.sepehr": "مشاور و هماهنگ‌کنندهٔ تیم و طراح UI/UX؛ یعنی اینکه صفحه‌ها نتیجهٔ بررسی را طوری نشان بدهند که با یک نگاه خوانده شود.",
  "team.bio.majid": "همگام‌سازی مدل‌های پروژه و طراحی UI/UX؛ یعنی اینکه مدل‌های متن، صدا و تصویر در یک موتور کنار هم کار کنند و صفحه‌ها آن‌ها را روشن نشان بدهند.",
  "about.title": "دربارهٔ Truth Guardian",
  "about.lead": "Truth Guardian طرح ما برای چالش ۴ هوش مصنوعی iWISE 2026 در تشخیص توهم است: نگهبانی که پاسخ هوش مصنوعی را کنار شواهدش می‌خواند، واژه‌هایی را که شواهد پشتیبانی‌شان نمی‌کند پیدا می‌کند، دلیلش را می‌گوید و هر چه بتواند اصلاح می‌کند.",
  "about.challengeTitle": "چالش",
  "about.challengeBody": "سامانه‌های هوش مصنوعی حتی وقتی اشتباه می‌کنند روان پاسخ می‌دهند. چالش این است که معلوم شود یک پاسخ بر سندهای بازیابی‌شده‌اش استوار است یا توهم، خطرش چقدر است، کدام بخش‌ها مشکوک‌اند و بر پایهٔ چه شاهدی؛ هم برای یک پاسخ و هم برای عامل چندمرحله‌ای. Truth Guardian این کار را اول برای متن انجام می‌دهد، و به‌عنوان افزوده‌های خود پروژه، پاسخ نشان‌دارشده را از روی منبع‌هایش اصلاح می‌کند و پاسخ دربارهٔ یک صدا یا یک تصویر را هم با آنچه گفته شده یا در آن نوشته شده می‌سنجد.",
  "about.engineTitle": "موتور چطور کار می‌کند",
  "about.engineBody": "برای پاسخی که از منابع متنی نوشته شده، پنج مرحله یکی پس از دیگری روی همین رایانه اجرا می‌شوند. هر مرحله شواهدی می‌افزاید که مرحلهٔ بعد از آن استفاده می‌کند و هر حکم را می‌توان تا واژه‌هایی که سببش شده‌اند دنبال کرد.",
  "about.s1.label": "شاهد",
  "about.s1.title": "برای هر جمله، شاهد پیدا کن",
  "about.s1.sub": "هر جملهٔ پاسخ با بخش‌هایی از منابع که می‌توانند پشتیبانش باشند جفت می‌شود؛ هم با واژه‌های کلیدی (BM25) و هم با معنا، و نتیجه‌ها بر اساس رتبه ترکیب می‌شوند.",
  "about.s2.label": "نشانه‌ها",
  "about.s2.title": "به چهار شکل مختلف بخوانش",
  "about.s2.sub": "هم‌پوشانی واژه‌ها؛ عددها، نام‌ها و تاریخ‌ها یکی‌یکی؛ شباهت معنایی؛ و HHEM، مدلی که برای سنجش سازگاری با واقعیت آموزش دیده است.",
  "about.s3.label": "ترکیب",
  "about.s3.title": "همه را به یک ریسک کالیبره تبدیل کن",
  "about.s3.sub": "یک مدل ترکیبی یادگرفته، نشانه‌ها را برای هر جمله و برای کل پاسخ وزن می‌دهد؛ ریسک آن را می‌توان احتمال خواند.",
  "about.s4.label": "قاعده‌ها",
  "about.s4.title": "آنچه مدل‌ها نمی‌بینند را بگیر",
  "about.s4.sub": "منفی‌سازی‌ها و واژه‌های متضاد که با NLI تأیید می‌شوند، نقش‌های جابه‌جاشده، ادعاهای اغراق‌آمیز، منابع ناهمسو و ارجاع‌هایی که به جای دیگری اشاره می‌کنند.",
  "about.s5.label": "گزارش",
  "about.s5.title": "توضیح بده، اصلاح کن، تضمین کن",
  "about.s5.sub": "واژه‌های دقیق، شاهد، اصلاحی از دل منابع، مقصر، آنچه جا افتاده، یک تضمین آماری، مسیر دسته‌بندی و یک نمره.",
  "about.runsTitle": "پردازش کجا انجام می‌شود",
  "about.runsBody": "همه‌چیز روی پردازندهٔ یک لپ‌تاپ معمولی اجرا می‌شود، بدون کارت گرافیک و بدون اینترنت. مدل‌های زبانی داخل پوشهٔ پروژه نگه داشته می‌شوند، سنگین‌ترین آن‌ها با ONNX Runtime اجرا می‌شود و جمله‌های تکراری از حافظهٔ موقت پاسخ می‌گیرند؛ برای همین هر بررسی چند ثانیه طول می‌کشد. هیچ پاسخ یا منبعی از رایانه خارج نمی‌شود.",
  "contact.title": "تماس با ما",
  "contact.lead": "پرسش، پیشنهاد یا مشکلی دارید؟ برای تیم Truth Guardian بنویسید؛ پیامتان مستقیم به صندوق ایمیل ما می‌رسد و با ایمیل پاسخ می‌دهیم.",
