  "card.short.summary": "خلاصه",
  "card.limit1": "روی RAGTruth (خبر، پرسش و پاسخ و داده‌های تجاری به زبان انگلیسی) آموزش دیده و کالیبره شده است. در دامنه‌ای دیگر رتبه‌بندی ضعیف‌تر است (AUROC روی HaluEval قفل‌شده: گفت‌وگو ۰٫۶۷ و خلاصه‌سازی ۰٫۶۹، خطای کالیبراسیون حدود ۰٫۲۳) تا وقتی که یک پروفایل دامنه روی چند ده پاسخ برچسب‌خورده ساخته شود؛ با ۵۰ پاسخ، روی پاسخ‌هایی که پروفایل ندیده، گفت‌وگو به حدود ۰٫۷۲ و خلاصه‌سازی به ۰٫۷۹ می‌رسد و خطای کالیبراسیون به حدود ۰٫۰۷ کم می‌شود.",
  "card.limit2": "برخی ویرایش‌ها هنوز عبور می‌کنند: واژهٔ متضاد در ۴۵٪ موارد گرفته می‌شود، کمیت‌نمای قوی‌تر در ۵۷٪ و قید احتیاط حذف‌شده در ۳۷٪ (از ۳۷٪ و ۲۰٪ پس از D-114 بالا رفته است).",
  "card.limit3": "روی اجراهای طبیعی عامل‌ها (AgentHallu) هیچ تنظیمی از نگهبان زنده عامل‌های درست را از عامل‌های دارای توهم به‌خوبی جدا نمی‌کند (AUROC تشخیص حدود ۰٫۵۳ روی آزمون قفل‌شده)؛ سه اصلاحی که بیرون از نمونهٔ آموزش امتحان شد تفاوتی ایجاد نکرد (D-116). پیدا کردن گام معیوب بهتر از شانس است، اما قابل اتکا نیست.",
  "card.limit4": "Span F1 روی آزمون قفل‌شدهٔ RAGTruth (۰٫۳۰) از dev (۰٫۳۸) پایین‌تر است: حکم کل پاسخ بهتر از جای دقیق خطا دوام می‌آورد. واژه‌های دقیق از آشکارساز آموزش‌دیده span F1 روی dev را به ۰٫۴۱ می‌رساند؛ آزمون قفل‌شده برای سنجیدن آن دوباره باز نشده است.",
  "card.limit5": "ویرایش‌های اصلاح اغلب درست‌اند اما نه همیشه: پیش از استفاده از پاسخ اصلاح‌شده، تغییرها را بخوانید.",
  "card.limit6": "پاسخ‌ها را فقط با منابع داده‌شده می‌سنجد. ادعایی که در دنیای واقعی درست است اما در منابع نیامده، بی‌پشتوانه به حساب می‌آید.",
