  "card.calibTitle": "آیا ریسک ۰٫۸ یعنی ۸۰٪؟ ریسک پیش‌بینی‌شده در برابر این‌که پاسخ‌ها واقعاً چند بار دارای توهم بودند",
  "card.calib1": "نقطه‌ای روی خط‌چین یعنی ریسک را می‌توان احتمال خواند: از پاسخ‌هایی که ریسکی نزدیک ۰٫۸ گرفته‌اند، حدود ۸۰٪ دارای توهم بودند. نقطه‌های زیر خط یعنی ریسک بالاتر از واقع است (محتاطانه)؛ بالای خط، پایین‌تر.",
  "card.calib2": "روی RAGTruth، که مدل روی آن کالیبره شده، نقطه‌ها هم روی dev و هم روی آزمون قفل‌شده نزدیک خط می‌مانند. روی آزمون، میانهٔ مقیاس کمی بالاست، پس نگهبان آن‌جا جانب احتیاط را می‌گیرد.",
  "card.calib3": "روی HaluEval، دامنه‌ای که هرگز ندیده، ریسک‌های پایین زیادی پایین و ریسک‌های بالا زیادی بالایند. به همین دلیل یک پروفایل دامنه، که روی چند ده پاسخ برچسب‌خورده از دامنهٔ تازه ساخته می‌شود، پیش از استفاده از تضمین‌ها ریسک را دوباره کالیبره می‌کند.",
  "card.calibNote": "ده بازهٔ ریسک با عرض برابر، همان که خطای کالیبراسیون (ECE) گزارش‌شده بر آن استوار است. برای دیدن عددها نشانگر را روی یک نقطه ببرید.",
  "card.profilesTitle": "یک دامنهٔ تازه با {n} پاسخ برچسب‌خورده: پروفایل‌های دامنهٔ همراه برنامه، سنجیده روی پاسخ‌هایی که ندیده‌اند",
