  "card.profilesNote": "هر پروفایل ریسک مدل و سه نشانهٔ شاهد را که روی جمله‌های پاسخ میانگین گرفته شده‌اند دوباره وزن می‌دهد، ریسک را دوباره کالیبره می‌کند و خطوط تضمین و حکم خود آن دامنه را تعیین می‌کند. هرگز از طول پاسخ استفاده نمی‌کند: روی HaluEval طول به‌تنهایی برچسب‌ها را جدا می‌کند{alone}، میان‌بری که هیچ دامنهٔ واقعی ندارد. HaluEval external dev؛ از مجموعه‌های قفل‌شدهٔ HaluEval استفاده نشد.",
