  "html.free.by.both": "نام‌برده توسط مدل و یافته‌شده توسط نگهبان",
  "html.free.n.main": "چون اسناد پاسخی نداشتند، یک مدل رایگان آنلاین جواب داد. نگهبان آن را همین‌جا با صفحه‌هایی که مدل نام برده و مقاله‌های ویکی‌پدیایی که خودش یافته سنجید؛ حکم «مستند» یعنی پاسخ با آنچه یافته شد می‌خواند، نه اینکه همهٔ صفحه‌ها درست‌اند.",
